import { readFile, writeFile } from "node:fs/promises";

// Generate a separate installation of the same audited financial rules.
const source = await readFile(
  new URL("../supabase/stardust.sql", import.meta.url),
  "utf8",
);
const sql = source
  .replace(
    "-- STARDUST WALLET v1. Run manually in Supabase SQL Editor. No legacy payment records are deleted.",
    "-- GENERATED by scripts/build-billing-sandbox.mjs. Test data only; public financial records are unchanged.",
  )
  .replace(
    "begin;",
    `begin;
create schema if not exists stardust_sandbox;
revoke all on schema stardust_sandbox from public, anon, authenticated;
grant usage on schema stardust_sandbox to authenticated, service_role;`,
  )
  .replace(
    "drop function if exists public.extend_ai_entitlement(uuid,text,integer);\n",
    "",
  )
  .replaceAll("public.stardust_", "stardust_sandbox.stardust_")
  .replaceAll("public.%I", "stardust_sandbox.%I")
  .replaceAll(
    "set search_path=public,pg_temp",
    "set search_path=stardust_sandbox,public,pg_temp",
  )
  .replaceAll("n.nspname='public'", "n.nspname='stardust_sandbox'");
if (sql.includes("public.stardust_") || sql.includes("extend_ai_entitlement"))
  throw new Error("Incomplete sandbox migration generation.");
await writeFile(
  new URL("../supabase/stardust-sandbox.sql", import.meta.url),
  sql,
);
console.log(
  "Generated supabase/stardust-sandbox.sql; no database connection was made.",
);
